const fs = require('fs');
const path = require('path');

const csvPath = path.join(__dirname, 'inventory.csv');
const reportPath = path.join(__dirname, 'report.md');

const rawData = fs.readFileSync(csvPath, 'utf8').trim();
const lines = rawData.split(/\r?\n/);
const headers = lines[0].split(',').map(h => h.trim());

let grandTotal = 0;
const rows = [];

for (let i = 1; i < lines.length; i++) {
  const line = lines[i].trim();
  if (!line) continue;
  const [item, qtyStr, priceStr] = line.split(',').map(s => s.trim());
  const quantity = parseInt(qtyStr, 10);
  const price = parseFloat(priceStr);
  const subtotal = quantity * price;
  grandTotal += subtotal;

  rows.push({
    item,
    quantity,
    price: price.toFixed(2),
    subtotal: subtotal.toFixed(2)
  });
}

let md = '# Inventory Report\n\n';
md += '| Item | Quantity | Unit Price | Subtotal |\n';
md += '| :--- | :---: | :---: | :---: |\n';

for (const row of rows) {
  md += `| ${row.item} | ${row.quantity} | $${row.price} | $${row.subtotal} |\n`;
}

md += `\n**Grand Total:** $${grandTotal.toFixed(2)}\n`;

fs.writeFileSync(reportPath, md, 'utf8');
console.log(`Report generated successfully at ${reportPath}`);
console.log(`Grand Total: $${grandTotal.toFixed(2)}`);
